import React from 'react';
import { useNavigate } from 'react-router-dom';

function LoginPage() {
    const navigate = useNavigate();
    return (
        <div style={{ padding: '40px', textAlign: 'center' }}>
            <h2>Вход на фитнес-платформу</h2>
            <button onClick={() => navigate('/account')} style={{ padding: '10px 20px', background: '#25598d', color: '#fff', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>
                Войти (Демо)
            </button>
        </div>
    );
}

export default LoginPage;
